arguments.new_str:
var builder = WebApplication.CreateBuilder(args);
builder.Services.AddScoped<IUserService, UserService>();
// Breaking change: ValidateOnBuild/ValidateScopes now enabled in development.
// A singleton capturing a scoped service throws. Use a factory pattern instead.
builder.Services.AddScoped<ICacheService>(sp =>
    new CacheService(sp.GetRequiredService<IUserService>()));
// Breaking change: HttpClientFactory now uses SocketsHttpHandler by default.
// Casting to HttpClientHandler throws InvalidCastException. Use ConfigurePrimaryHttpMessageHandler.
builder.Services.AddHttpClient("api")
    .ConfigurePrimaryHttpMessageHandler(() => new HttpClientHandler { UseCookies = false });
// Breaking change: ForwardedHeadersMiddleware now ignores X-Forwarded-* from unknown proxies.
// You must register trusted proxy addresses.
builder.Services.Configure<ForwardedHeadersOptions>(options =>
{
    options.ForwardedHeaders = ForwardedHeaders.XForwardedFor;
    // TODO: Replace with your actual reverse proxy IP address(es)
    options.KnownProxies.Add(System.Net.IPAddress.Parse("127.0.0.1"));
});
// Breaking change: HttpClientFactory Trace-level logs now redact all header values by default.
// Allowlist specific non-sensitive headers you need to see for debugging.
builder.Services.ConfigureHttpClientDefaults(b =>
    b.RedactLoggedHeaders(header =>
        header != "X-Request-Id" && header != "X-Correlation-Id"));
var app = builder.Build();
app.UseForwardedHeaders();
app.Run();

